<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {onMount} from 'svelte';import {refreshAll} from '$app/navigation';import {calculateLines} from '@schubert/domain';import type {AppData,Row} from '#lib/client/types.ts';import {request,display,recordName} from '#lib/client/api.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import PortalUpload from './PortalUpload.svelte';import PortalDeclarations from './PortalDeclarations.svelte';
  let {data}:{data:AppData}=$props();let password=$state('');let busy=$state(false);let error=$state('');let notice=$state('');let body=$state('');let senderName=$state('');let selected:Row|null=$state(null);let declarationKind=$state('');let statement=$state('');let confirmed=$state(false);let selectedProject=$state('');let declarationKey=$state('');let selectedOptions:number[]=$state([]);let messageKey=$state('');let ready=$state(false);let senderInitialized=$state(false);
  onMount(()=>{messageKey=crypto.randomUUID();ready=true;});
  $effect(()=>{if(authenticated&&!senderInitialized&&data.summary?.identityAssurance==='individual_session'&&data.summary?.contactName){senderName=data.summary.contactName;senderInitialized=true;}});
  async function logout(){if(busy)return;busy=true;error='';try{await request('/api/v1/portal/logout',{});password='';senderName='';senderInitialized=false;selected=null;await refreshAll();}catch(e){error=e instanceof Error?e.message:'Der Zugang konnte nicht geschlossen werden.';}finally{busy=false;}}

  const token=$derived(data.path.split('/').filter(Boolean)[1]||data.summary?.portalToken||'');
  const authenticated=$derived(data.summary?.portalAuthenticated??data.portal?.authenticated??false);const publications=$derived(data.related?.publications||data.records||[]);const messages=$derived(data.related?.messages||[]);const projects=$derived(data.related?.projects||[]);const visible=$derived(selectedProject?publications.filter((p:Row)=>p.order_id===selectedProject||p.project_id===selectedProject):publications);
  const publicationKinds:Record<string,string>={quote:'Angebot',quotes:'Angebot',invoice:'Rechnung',invoices:'Rechnung',design:'Entwurf',planning:'Planung',document:'Unterlage',delivery:'Lieferumfang',acceptance:'Abnahmeumfang'};
  const declarations=[{kind:'quote_acceptance',label:'Angebot verbindlich annehmen',button:'Zahlungspflichtig beauftragen'},{kind:'design',label:'Gestaltung freigeben',button:'Diese Gestaltung freigeben'},{kind:'inscription',label:'Inschrift bestätigen',button:'Wortlaut und Schreibweise bestätigen'},{kind:'change_request',label:'Änderung wünschen',button:'Änderungswunsch übermitteln'},{kind:'delivery',label:'Lieferung bestätigen',button:'Diesen Lieferumfang bestätigen'},{kind:'acceptance',label:'Werkleistung abnehmen',button:'Werkleistung abnehmen'},{kind:'withdrawal',label:'Vertrag widerrufen',button:'Widerruf bestätigen'}];
  const optionLines=$derived.by(()=>(selected?.lines||[]).map((line:Row,index:number)=>({...line,position:line.position??index+1})).filter((line:Row)=>line.optional));
  const optionTotals=$derived.by(()=>{if(declarationKind!=='quote_acceptance'||!optionLines.length)return null;try{if(!(selected?.lines||[]).every((line:Row)=>line.tax_rate!==undefined&&line.discount_percent!==undefined&&line.unit_price!==undefined))return null;return calculateLines((selected?.lines||[]).map((line:Row,index:number)=>({...line,selected:line.optional?selectedOptions.includes(line.position??index+1):true})) as any);}catch{return null;}});
  function download(pub:Row){return pub.download_url||`/api/v1/portal/publications/${pub.id}/download`;}
  function allowed(pub:Row){const actions=pub.allowed_actions||pub.actions||[];return declarations.filter(d=>actions.includes(d.kind)||actions.some((a:any)=>a.kind===d.kind));}
  async function login(event:SubmitEvent){event.preventDefault();busy=true;error='';try{await request('/api/v1/portal/login',{token,password});password='';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Der Zugang konnte nicht geöffnet werden.';}finally{busy=false;}}
  async function message(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';try{await request('/api/v1/portal/messages',{body,sender_name:senderName,publication_id:selected?.id,idempotencyKey:messageKey});body='';messageKey=crypto.randomUUID();notice='Ihre Nachricht ist bei Schubert eingegangen.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Nachricht konnte nicht gesendet werden.';}finally{busy=false;}}
  async function declare(event:SubmitEvent){event.preventDefault();if(!selected||!confirmed)return;busy=true;error='';try{await request('/api/v1/portal/declarations',{kind:declarationKind,publication_id:selected.id,statement,person_name:senderName,confirmed:true,idempotencyKey:declarationKey,selected_options:declarationKind==='quote_acceptance'?selectedOptions:undefined});notice=declarationKind==='withdrawal'?'Ihr Widerruf ist eingegangen. Der Eingangsnachweis wird separat bereitgestellt.':'Ihre Erklärung wurde mit dem angezeigten Versionsstand gespeichert.';selected=null;statement='';confirmed=false;await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Ihre Erklärung konnte nicht gespeichert werden. Prüfen Sie den aktuellen Stand.';}finally{busy=false;}}
  function openDeclaration(publication:Row,kind:string){selected=publication;declarationKind=kind;declarationKey=crypto.randomUUID();selectedOptions=(publication.lines||[]).map((line:Row,index:number)=>({...line,position:line.position??index+1})).filter((line:Row)=>line.optional&&line.selected).map((line:Row)=>line.position);confirmed=false;statement='';error='';}
</script>
<div class="portal-shell"><header class="portal-topbar"><div class="brand"><div class="brand-name">SCHUBERT</div><div class="brand-sub">IHR PERSÖNLICHER PROJEKTBEREICH</div></div><div class="inline-actions"><span class="small muted"><Icon name="lock" size={14}/> Geschützter Zugang</span>{#if authenticated}<button class="btn small" disabled={busy||!ready} onclick={logout}>Zugang schließen<Icon name="logout" size={15}/></button>{/if}</div></header>{#if !authenticated}<form class="portal-login" onsubmit={login}><h1 style="font-size:29px;margin-top:12px">Ihr Vorhaben.<br/>Gemeinsam im Blick.</h1><p class="small mt">Öffnen Sie Ihre freigegebenen Entwürfe, Unterlagen und Nachrichten mit dem erhaltenen Passwort.</p>{#if error}<div class="notice error mt" role="alert">{error}</div>{/if}<div class="field"><label for="portal-password">Portalpasswort</label><input id="portal-password" type="password" bind:value={password} autocomplete="current-password" required/></div><button class="btn primary full" disabled={busy||!token||!ready}>{busy?'Zugang wird geprüft …':!ready?'Zugang wird vorbereitet …':'Projektbereich öffnen'}<Icon name="arrow" size={16}/></button>{#if !token}<p class="field-error mt">Bitte öffnen Sie den vollständigen Portal-Link, den Sie von Schubert erhalten haben.</p>{/if}</form>{:else}<main class="portal-content"><div class="page-heading"><div><h1>Ihr Vorhaben.</h1><p>{data.summary?.portalWelcome||'Alle bewusst für Sie freigegebenen Stände, Unterlagen und nächsten Schritte an einem Ort.'}</p></div>{#if data.summary?.contact}<div class="small"><span class="muted">Ihr Kontakt</span><br/><strong>{data.summary.contact.name}</strong>{#if data.summary.contact.phone}<br/><a href={`tel:${data.summary.contact.phone}`}>{data.summary.contact.phone}</a>{/if}</div>{/if}</div>{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}{#if projects.length>1}<div class="field mb"><label for="portal-project">Vorhaben auswählen</label><select use:searchableSelect={selectedProject} id="portal-project" bind:value={selectedProject}><option value="">Alle freigegebenen Vorhaben</option>{#each projects as project}<option value={project.id}>{recordName(project)}</option>{/each}</select></div>{/if}
{#if data.summary?.identityAssurance==='shared_access'}<div class="notice info"><Icon name="users"/><div>Dies ist ein gemeinsamer Kundenzugang. Geben Sie bei Nachrichten Ihren eigenen Namen an. Verbindliche Beauftragungen benötigen einen persönlich freigeschalteten Kontaktzugang.</div></div>{/if}{#each visible as publication}<article class="publication"><p class="publication-context">{publicationKinds[publication.kind||publication.entity_type]||'Freigegebene Unterlage'} · {display(publication.published_at||publication.created_at,'created_at')}{publication.version?` · Version ${publication.version}`:''}</p><h2 class="mt">{recordName(publication)}</h2>{#if publication.status}<Status value={publication.status}/>{/if}{#if publication.accuracy_label}<div class="notice info mt">{publication.accuracy_label}</div>{/if}{#if publication.body||publication.description||publication.content}<div class="publication-body">{typeof publication.content==='object'?publication.body||publication.description||'':publication.body||publication.description||publication.content}</div>{/if}{#if publication.inscription_text}<section class="action-preview mt"><p class="publication-context">Inschrift · Wortlaut zur Prüfung</p><p class="publication-body" style="font-size:19px;color:var(--ink)">{publication.inscription_text}</p></section>{/if}{#if publication.total_gross||publication.gross_total}<p class="mt"><strong>{publication.entity_type==='quote'?'Angebotssumme des veröffentlichten Stands':'Gesamtpreis'} {display(publication.total_gross||publication.gross_total,'gross_amount')}</strong></p>{/if}{#if publication.terms}<p class="small mt" style="white-space:pre-wrap">{publication.terms}</p>{/if}{#if publication.inscriptions?.length}<div class="action-preview mt"><p class="publication-context">Inschrift · Wörtliche Textprüfung</p>{#each publication.inscriptions as inscription}<p class="publication-body" style="font-size:19px;color:var(--ink)">{inscription.text}</p><p class="field-help">{inscription.referenceStatus==='shop_image_reference'?'Hersteller-Bildreferenz · keine verifizierte Konturgeometrie':inscription.referenceStatus||''}</p>{/each}</div>{/if}{#if publication.lines?.length}<div class="table-scroll mt portal-lines"><table class="data-table"><thead><tr><th>Leistung</th><th class="number">Menge / Einheit</th><th class="number">Einzelpreis netto</th></tr></thead><tbody>{#each publication.lines as line}<tr><td>{line.description}{#if line.optional}<p class="record-subtitle">Option · {line.selected?'ausgewählt':'nicht im Umfang'}</p>{/if}</td><td class="number">{display(line.quantity,'quantity')} {display(line.unit)}</td><td class="number" data-label="Einzelpreis netto">{display(line.unit_price,'unit_price')}</td></tr>{/each}</tbody></table></div>{/if}<div class="publication-actions">{#if publication.document_id||publication.document_version_id||publication.download_url}<a class="btn" data-sveltekit-reload download href={download(publication)}><Icon name="download" size={16}/>Unterlage herunterladen</a>{/if}{#each allowed(publication) as action}<button class:danger={action.kind==='withdrawal'} class="btn primary" disabled={busy||!ready} onclick={()=>openDeclaration(publication,action.kind)}>{action.label}</button>{/each}</div></article>{/each}{#if !visible.length}<section class="panel"><div class="empty-state"><div class="empty-icon"><Icon name="file"/></div><h3>Alles bereit für die nächsten Schritte</h3><p>Sobald Schubert Unterlagen für Ihr Vorhaben veröffentlicht, finden Sie diese hier. Schreiben Sie bei Fragen eine Nachricht.</p></div></section>{/if}
<PortalDeclarations declarations={data.related?.declarations||[]}/><PortalUpload publications={publications}/><section class="panel mt"><header class="panel-header"><h2>Nachrichten zu Ihrem Vorhaben</h2><Icon name="mail" size={18}/></header><div class="panel-body">{#each messages as message}<article class="portal-message"><strong>{message.sender_name||message.author_name||'Projektbeteiligte'}</strong><div class="mt">{message.body}</div><p>{display(message.created_at,'created_at')}{message.identity_assurance==='shared_access'?' · Absendername selbst angegeben':''}</p></article>{/each}<form class="form-section" onsubmit={message}><div class="field mb"><label for="portal-name">Ihr Name *</label><input id="portal-name" bind:value={senderName} autocomplete="name" required/></div><div class="field"><label for="portal-message">Nachricht oder Änderungswunsch *</label><textarea id="portal-message" bind:value={body} required></textarea><span class="field-help">Ein Änderungswunsch verändert noch keinen freigegebenen Entwurf oder Auftrag.</span></div><button class="btn primary mt" type="submit" disabled={busy}>{busy?'Wird gesendet …':'Nachricht senden'}<Icon name="arrow" size={16}/></button></form></div></section></main>{/if}<footer class="portal-footer"><a class="text-link" href="/withdrawal">Widerruf ohne Portal-Anmeldung übermitteln</a></footer></div>
{#if selected}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" use:focusTrap aria-modal="true" aria-labelledby="portal-declaration-title" tabindex="-1" onkeydown={(e)=>{if(e.key==='Escape'&&!busy)selected=null;}}><header class="modal-header"><div><h2 id="portal-declaration-title">{declarations.find(d=>d.kind===declarationKind)?.label}</h2></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={()=>selected=null}><Icon name="close"/></button></header><form onsubmit={declare} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<div class="action-preview"><h3>{recordName(selected)}</h3><p class="small">Version {selected.revision||selected.version||selected.revision_id||'in Veröffentlichung gebunden'}</p>{#if selected.inscription_text}<p class="publication-body">{selected.inscription_text}</p>{/if}{#if (selected.total_gross||selected.gross_total)&&!(declarationKind==='quote_acceptance'&&optionLines.length)}<p class="mt"><strong>Gesamtbrutto {display(selected.total_gross||selected.gross_total,'gross_amount')}</strong></p>{/if}<p class="small mt" style="white-space:pre-wrap">{selected.declaration_text||selected.terms||selected.body||selected.description}</p>{#if selected.document_id||selected.document_version_id||selected.download_url}<a class="text-link mt" data-sveltekit-reload download href={download(selected)}>Vertragsunterlagen herunterladen<Icon name="download" size={14}/></a>{/if}</div><section class="mb">{#if declarationKind==='quote_acceptance'&&optionLines.length}<h3 style="font-size:16px;margin-bottom:14px">Gewünschte Optionen auswählen</h3><p class="field-help mb">Die festen Leistungen bleiben Bestandteil des Angebots. Wählen Sie zusätzliche optionale Positionen bewusst aus.</p>{#each optionLines as line}<label class="check-field mb"><input type="checkbox" value={line.position} bind:group={selectedOptions}/><span>Position {line.position}: {line.description}<span class="field-help" style="display:block">{display(line.quantity,'quantity')} {display(line.unit)} · Einzelpreis {display(line.unit_price,'unit_price')} netto</span></span></label>{/each}{#if optionTotals}<div class="action-preview"><p class="small">Gesamtpreis Ihrer ausgewählten Leistungen</p><strong style="font-size:21px">{display(optionTotals.gross_total,'gross_amount')} brutto</strong><p class="field-help mt">Enthält {display(optionTotals.tax_total,'tax_total')} Umsatzsteuer. Der Server prüft denselben eingefrorenen Angebotsstand vor der Annahme.</p></div>{:else}<div class="notice warning">Die ausgewählte Summe kann mit den bereitgestellten Angaben noch nicht geprüft werden. Bitten Sie Schubert um einen vollständigen Angebotsstand.</div>{/if}{/if}</section><div class="field mb"><label for="declaration-name">Vollständiger Name *</label><input id="declaration-name" bind:value={senderName} autocomplete="name" required/></div><div class="field"><label for="declaration-statement">Ihre Erklärung *</label><textarea id="declaration-statement" bind:value={statement} required minlength="5"></textarea></div><label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>{declarationKind==='withdrawal'?'Ich möchte den bezeichneten Vertrag widerrufen.':'Ich habe den bezeichneten Stand und die zugehörigen Unterlagen geprüft und bin berechtigt, diese Erklärung abzugeben.'}</span></label><p class="field-help mt">{declarationKind==='inscription'?'Diese Bestätigung betrifft ausschließlich Wortlaut und Schreibweise der bezeichneten Inschrift.':declarationKind==='design'?'Diese Freigabe betrifft die bezeichnete Gestaltung. Technische Fertigungsfreigaben erfolgen separat.':'Die Erklärung wird mit dem angezeigten Inhalt und Versionsstand nachweisbar gespeichert.'}</p></div><footer class="modal-footer"><button class="btn" type="button" disabled={busy} onclick={()=>selected=null}>Abbrechen</button><button class="btn primary" type="submit" disabled={busy||!confirmed||declarationKind==='quote_acceptance'&&optionLines.length>0&&!optionTotals}>{busy?'Wird gespeichert …':declarations.find(d=>d.kind===declarationKind)?.button}</button></footer></form></div></div>{/if}
